import java.util.*;

public class Main {
    static List<Integer> findClosestElementsBrute(int[] arr, int k, int x) {
        List<Integer> all = new ArrayList<>();
        for (int v : arr) all.add(v);
        all.sort((a, b) -> Math.abs(a - x) != Math.abs(b - x) ?
            Integer.compare(Math.abs(a - x), Math.abs(b - x)) : Integer.compare(a, b));  // sort by distance
        List<Integer> closestK = new ArrayList<>(all.subList(0, k));
        Collections.sort(closestK);                                                        // re-sort by value
        return closestK;
    }
}

