vector<int> findClosestElementsBrute(vector<int>& arr, int k, int x) {
    vector<int> all = arr;
    sort(all.begin(), all.end(), [&](int a, int b) {
        int da = abs(a - x), db = abs(b - x);
        return da != db ? da < db : a < b;                             // sort by distance
    });
    vector<int> closestK(all.begin(), all.begin() + k);
    sort(closestK.begin(), closestK.end());                             // re-sort by value
    return closestK;
}

