def find_closest_elements(arr, k, x):
    lo, hi = 0, len(arr) - k
    while lo < hi:
        mid = (lo + hi) // 2
        if x - arr[mid] > arr[mid + k] - x:
            lo = mid + 1                     # right edge is closer, shift window right
        else:
            hi = mid                          # left edge is at least as close, shift/keep left
    return arr[lo:lo + k]

