#include <bits/stdc++.h>
using namespace std;

vector<int> findClosestElements(vector<int>& arr, int k, int x) {
    int lo = 0, hi = (int)arr.size() - k;
    while (lo < hi) {
        int mid = (lo + hi) / 2;
        if (x - arr[mid] > arr[mid + k] - x) lo = mid + 1;      // shift window right
        else hi = mid;                                            // shift/keep left
    }
    return vector<int>(arr.begin() + lo, arr.begin() + lo + k);
}
